    return () => {
      clearTimeout(timer);
    };
  }, [request, query, contains]);

  return (
    <Autocomplete
      items={results}
      autoHighlight
      filter={null}
      value={query}
      onValueChange={(query) => {
        const next = { query };
        setRequest(next);

        if (!query) {
          setResponse({ request: next, results: [] });
