    theme: {
      foreground: "var(--foreground)",
      grid: "var(--border)",
      muted: "var(--muted-foreground)",
    },
    ...(options.tooltip
      ? {
          focus: "group-x" as const,
          tooltip: { className: "erbium-chart-tooltip", use: tooltip },
        }
      : {}),
  });
}

export function ChartExample() {
  return (
    <Chart
      definition={visitorChart()}
