      name: "types",
    },
    {
      items: [{ name: "favicon.ico" }, { name: "logo.svg" }, { name: "images" }],
      name: "public",
    },
    { name: "app.tsx" },
    { name: "layout.tsx" },
    { name: "globals.css" },
    { name: "package.json" },
    { name: "tsconfig.json" },
    { name: "README.md" },
