              {["Open project", "Rename project", "Duplicate project", "Copy project link"].map(
                (label) => (
                  <ContextMenuItem
                    key={label}
                    label={label}
                    onClick={() => {
                      setAction(label);
                    }}
                  >
                    {label}
                  </ContextMenuItem>
                ),
              )}
            </ContextMenuGroup>

            <ContextMenuGroup>
              <ContextMenuLabel>Export</ContextMenuLabel>
              {["Export PDF", "Export Markdown", "Export CSV", "Download archive"].map((label) => (
                <ContextMenuItem
                  key={label}
                  label={label}
                  onClick={() => {
                    setAction(label);
                  }}
                >
                  {label}
                </ContextMenuItem>
              ))}
            </ContextMenuGroup>
          </ContextMenuList>
        </ContextMenuContent>
      </ContextMenu>
      <p role="status" className="text-caption text-muted-foreground">
        {action}
      </p>
    </div>
  );
}

