import TanstackFormExample from "./variants/tanstack-form";
const TanstackFormSource = "import { useState } from "react";
import { useForm, useStore } from "@tanstack/react-form";
import { StepIndicator, StepIndicatorItem } from "@/registry/erbium/blocks/step-indicator";
import { Button } from "@/registry/erbium/ui/button";
import { Field, FieldError, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";

const steps = [
  { field: "name", label: "Name" },
  { field: "email", label: "Email" },
  { field: "company", label: "Company" },
] as const;

const required = ({ value }: { value: string }) => (value.trim() ? undefined : "Required");

export default function Example() {
  const [step, setStep] = useState(0);
  const [done, setDone] = useState(false);

  const form = useForm({
    defaultValues: { company: "", email: "", name: "" },
    onSubmit: () => {
      setDone(true);
    },
    // Submit validates every step. Send the user to the first one that failed.
    onSubmitInvalid: ({ formApi }) => {
      const first = steps.findIndex((item) => !formApi.getFieldMeta(item.field)?.isValid);

      if (first !== -1) {
        setStep(first);
      }
    },
  });

  const fieldMeta = useStore(form.store, (state) => state.fieldMeta);

  // A step shows an error only after the user has touched it: by typing and
  // blurring, or by trying to move past it. Untouched steps stay quiet.
  const hasError = (field: (typeof steps)[number]["field"]) =>
    Boolean(fieldMeta[field]?.isTouched && !fieldMeta[field]?.isValid);

  // Going back is free. Going forward validates each step on the way, which
  // touches it, and stops at the first invalid one. Later steps are never
  // validated, so they never show an error before the user reaches them.
  async function goTo(target: number) {
    for (let index = step; index < target; index++) {
      const errors = await form.validateField(steps[index].field, "change");

      if (errors.length) {
        setStep(index);

        return;
      }
    }

    setStep(target);
  }

  return (
    <form
      className="flex w-72 flex-col items-center gap-4"
      onSubmit={(event) => {
        event.preventDefault();
        void form.handleSubmit();
      }}
    >
      <StepIndicator value={step} onValueChange={goTo}>
        {steps.map((item, index) => (
          <StepIndicatorItem
            key={item.field}
            index={index}
            label={item.label}
            invalid={hasError(item.field)}
          />
        ))}
      </StepIndicator>
      {/* Every field stays mounted so validateField always finds its validators.
          Only the current step is visible. */}
      {steps.map((item, index) => (
        <form.Field key={item.field} name={item.field} validators={{ onChange: required }}>
          {(field) => {
            const invalid = field.state.meta.isTouched && !field.state.meta.isValid;

            return (
              <Field className="w-full" name={field.name} invalid={invalid} hidden={index !== step}>
                <FieldLabel>{item.label}</FieldLabel>
                <Input
                  value={field.state.value}
                  onChange={(event) => {
                    field.handleChange(event.target.value);
                  }}
                  onBlur={field.handleBlur}
                />
                <FieldError errors={invalid ? field.state.meta.errors : []} />
              </Field>
            );
          }}
        </form.Field>
      ))}
      <div className="flex gap-2">
        <Button
          type="button"
          variant="outline"
          disabled={step === 0}
          onClick={async () => {
            await goTo(step - 1);
          }}
        >
          Back
        </Button>
        {step < steps.length - 1 ? (
          <Button
            type="button"
            onClick={async () => {
              await goTo(step + 1);
            }}
          >
            Next
          </Button>
        ) : (
          <Button type="submit">{done ? "Saved" : "Finish"}</Button>
        )}
      </div>
    </form>
  );
}
";

const meta = {
  parameters: {
    docs: { description: { component: "## Usage

Import from `@/registry/erbium/blocks/step-indicator`. Pass `count` and the zero-based `value` of the current step. Passing `onValueChange` makes every step selectable; without it the indicator is read-only.

```tsx
const [step, setStep] = useState(0);

<StepIndicator count={4} value={step} onValueChange={setStep} />;
```

The indicator only displays position. It never renders step content, owns navigation rules, or validates. Wire it to whatever does: a form, Tabs, a router, or a Questionnaire.

## Composition

Use `StepIndicatorItem` children when steps need their own state or names. Each item takes its zero-based `index`.

```tsx
<StepIndicator value={step} onValueChange={setStep}>
  {steps.map((item, index) => (
    <StepIndicatorItem key={item.id} index={index} label={item.label} invalid={item.invalid} />
  ))}
</StepIndicator>
```

`count` is shorthand for rendering default items and is ignored when children are provided.

## API

`StepIndicator`

- `value`, `defaultValue`, `onValueChange(index)`: zero-based current step. Follows the Base UI controlled and uncontrolled convention. `onValueChange` also turns the items into buttons.
- `count`: shorthand for that many default items.
- `reach`: furthest step index that can be selected. Steps after it are blocked: no hover, not-allowed cursor, and clicks ignored. The current step is never blocked. Defaults to no limit.
- `progress`: fills the current step from 0 to 1. Defaults to 1.
- `orientation`: `horizontal` (default) or `vertical`.
- `render`: replaces the `ol`. Receives `{ value, count, orientation, interactive }`.

`StepIndicatorItem`

- `index`: position of the step.
- `status`: `complete`, `current` or `upcoming`. Derived from `value` by default (earlier steps are complete); set it when completion is not linear.
- `invalid`: marks the step as having errors.
- `disabled`: blocks this step, for arbitrary rules that `reach` cannot express.
- `label`: accessible name. Defaults to "Step N"; ", completed" and ", has errors" are appended. Translate it by passing your own.
- `render`: replaces the control (a `button` when interactive, otherwise a `span`), for example to render a router link. Receives `{ index, status, invalid, disabled }`.

## Hover and blocking

Interactive steps get a simple hover area around the dot. Blocked steps show a not-allowed cursor and no hover. There are two ways to block, and they combine:

- Declarative: `reach` for linear flows (nothing past the furthest step reached), `disabled` on an item for anything else.
- Imperative: refuse inside `onValueChange`, for rules that need async work such as validation. See the TanStack Form example.

## Styling and accessibility

Items expose `data-status`, `data-invalid` and `data-disabled`; the root and items expose `data-orientation`. The root is an ordered list labeled "Progress" and the current step has `aria-current="step"`. Give the root an `aria-label` that names the sequence. Transitions respect reduced motion and the layout mirrors under RTL." } },
    layout: "centered",
  },
} satisfies Meta;

